"""Tenant identity and permission records."""
from dataclasses import dataclass, field
from typing import Set, Dict, Any, List

@dataclass
class TenantContext:
    tenant_id: str
    tenant_name: str = ""
    allowed_scopes: Set[str] = field(default_factory=set)
    is_active: bool = True

    def permits(self, scope: str) -> bool:
        if not self.is_active:
            return False

        # Exact match
        if scope in self.allowed_scopes:
            return True

        # Wildcard matching per H06
        required_segments = scope.split("::")

        for allowed_scope in self.allowed_scopes:
            pattern_segments = allowed_scope.split("::")
            if self._match_pattern(pattern_segments, required_segments):
                return True

        return False

    def _match_pattern(self, pattern: List[str], target: List[str]) -> bool:
        p_idx = 0
        t_idx = 0

        while p_idx < len(pattern) and t_idx < len(target):
            p_seg = pattern[p_idx]

            if p_seg == "**":
                # ** matches arbitrary remaining segments if at the end of pattern
                if p_idx == len(pattern) - 1:
                    return True
                else:
                    # Fallback for ** in middle (not specified but safe to fail or skip)
                    # H06 says "matches arbitrary multi-segment prefixes". 
                    # Assuming ** is only used at the end of a scope pattern.
                    return False
            elif p_seg == "*":
                # Matches exactly one segment
                t_idx += 1
                p_idx += 1
            else:
                if p_seg != target[t_idx]:
                    return False
                t_idx += 1
                p_idx += 1

        # If pattern exhausted, ensure target is also exhausted (unless ** was handled)
        if p_idx == len(pattern):
            return t_idx == len(target)

        return False

    def add_scope(self, scope: str) -> None:
        self.allowed_scopes.add(scope)

    def to_dict(self) -> Dict[str, Any]:
        return {"tenant_id": self.tenant_id, "tenant_name": self.tenant_name, "is_active": self.is_active}
